#!/usr/bin/env bash
# Regenerates the documentation screenshots in site/public/screenshots from the real UI. Everything shown is fictional: a
# fresh, throwaway local stack (scripts/dev-stack.sh) with its own herdr-core core and a stub harness, seeded by
# web/e2e/screenshots.spec.ts with example.com people and invented spaces. Credentials are generated by that stack and
# destroyed with it. Review every image before committing it, and update docs/SCREENSHOTS.md.
#
# Usage: scripts/screenshots.sh [OUT_DIR]   (default site/public/screenshots)
# Needs Go, pnpm, hc and the Playwright Chromium browser (cd web && pnpm exec playwright install chromium).
set -euo pipefail

root=$(cd "$(dirname "$0")/.." && pwd)
out=$(mkdir -p "${1:-$root/site/public/screenshots}" && cd "${1:-$root/site/public/screenshots}" && pwd)
command -v hc >/dev/null || { echo "screenshots need herdr-core (hc) on PATH" >&2; exit 2; }
dir=$("$root/scripts/dev-stack.sh" up | tail -1)
trap '"$root/scripts/dev-stack.sh" down "$dir"' EXIT
# shellcheck disable=SC1091
source "$dir/env"
cd "$root/web"
SM_SCREENSHOTS_OUT="$out" pnpm exec playwright test e2e/screenshots.spec.ts --reporter=list
echo "screenshots written to $out"
